class Refusal(RuntimeError):
    """Raised for an input or custody condition which must fail closed."""


def sha_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def sha_file(path: Path) -> str:
    if path.is_symlink() or not path.is_file():
        raise Refusal(f"not a regular non-symlink file: {path}")
    return sha_bytes(path.read_bytes())


def read_json(path: Path) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
        raise Refusal(f"invalid JSON {path}: {error}") from error


def write_json(path: Path, value: Any) -> None:
    path.write_text(
        json.dumps(value, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def integer(value: Any) -> int:
    if isinstance(value, int) and not isinstance(value, bool):
        return value
    if isinstance(value, str):
        try:
            return int(value, 0)
        except ValueError as error:
            raise Refusal(f"invalid integer encoding: {value!r}") from error
    raise Refusal(f"not an integer encoding: {value!r}")


def canonical_json_digest(value: Any) -> str:
    return sha_bytes(json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8"))


def verify_frozen() -> dict[str, str]:
    actual: dict[str, str] = {}
    mismatch: dict[str, dict[str, str]] = {}
    for relative, expected in FROZEN.items():
        observed = sha_file(ROOT / relative)
        actual[relative] = observed
        if observed != expected:
            mismatch[relative] = {"expected": expected, "observed": observed}
    if mismatch:
        raise Refusal("frozen input digest mismatch: " + json.dumps(mismatch, sort_keys=True))
    return actual


def load_cohort() -> tuple[list[dict[str, Any]], dict[str, Any]]:
    cohort = read_json(COMPAT / "cohort-inputs.json")
    runtime = read_json(COMPAT / "runtime-bindings.json")
    rows = cohort.get("rows")
    fields = {"curve_uid", "curve_id", "label", "n", "p", "ordinal", "seed_hex", "timestamp"}
    if not isinstance(rows, list) or len(rows) != 21:
        raise Refusal("cohort does not contain exactly 21 rows")
    if any(not isinstance(row, dict) or set(row) != fields for row in rows):
        raise Refusal("cohort row schema mismatch")
    if len({row["curve_uid"] for row in rows}) != 21:
        raise Refusal("cohort has duplicate curve UIDs")
    if [row["label"] for row in rows].count("omitted") != 11:
        raise Refusal("cohort omitted-label count mismatch")
    if [row["label"] for row in rows].count("published") != 10:
        raise Refusal("cohort published-label count mismatch")
    return rows, runtime


def canonical_sources() -> dict[str, tuple[str, dict[str, Any]]]:
    """Select only the two canonical, non-overlapping record collections.

    ``traits.unpublished_candidates`` is intentionally not recursively merged:
    it contains copies of omitted material and is not the canonical omitted
    source.  ``traits.published_controls`` is a dictionary of named controls.
    """
    assessed = read_json(ROOT / "research/nist_seed_skipped_curves_20261016/assessed.json")
    traits = read_json(ROOT / "research/nist_seed_skipped_curves_20261016/traits.json")
    omitted = assessed.get("candidate_rows")
    published = traits.get("published_controls")
    if not isinstance(omitted, list) or len(omitted) != 11:
        raise Refusal("assessed.candidate_rows is not the canonical 11-row omitted source")
    if not isinstance(published, dict) or len(published) != 10:
        raise Refusal("traits.published_controls is not the canonical 10-row named source")

    chosen: dict[str, tuple[str, dict[str, Any]]] = {}
    for label, records in (("omitted", omitted), ("published", list(published.values()))):
        for record in records:
            if not isinstance(record, dict):
                raise Refusal("canonical provenance record is not an object")
            identity = record.get("identity")
            if not isinstance(identity, dict) or not isinstance(identity.get("curve_uid"), str):
                raise Refusal("canonical provenance identity is incomplete")
            uid = identity["curve_uid"]
            if uid in chosen:
                raise Refusal(f"duplicate canonical provenance UID: {uid}")
            chosen[uid] = (label, record)
    if len(chosen) != 21:
        raise Refusal("canonical provenance collections do not yield exactly 21 UIDs")
    return chosen


def prior_mapping(rows: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    chosen = canonical_sources()
    corpus_path = ROOT / "research/nist_seed_selection_20261016/raw/full_prime_order_certificates.jsonl"
    corpus = [json.loads(line) for line in corpus_path.read_text(encoding="utf-8").splitlines() if line]
    result: dict[str, dict[str, Any]] = {}

    for row in rows:
        selected = chosen.get(row["curve_uid"])
        if selected is None:
            raise Refusal(f"missing canonical provenance record: {row['curve_uid']}")
        label, source = selected
        identity = source.get("identity", {})
        curve = identity.get("curve", {})
        field = identity.get("field", {})
        if label != row["label"]:
            raise Refusal(f"canonical label mismatch: {row['curve_uid']}")
        if identity.get("curve_id") != row["curve_id"]:
            raise Refusal(f"canonical curve_id mismatch: {row['curve_uid']}")
        if integer(field.get("characteristic")) != integer(row["p"]):
            raise Refusal(f"canonical p mismatch: {row['curve_uid']}")
        if integer(curve.get("subgroup_order")) != integer(row["n"]):
            raise Refusal(f"canonical n mismatch: {row['curve_uid']}")
        if curve.get("cofactor") != 1:
            raise Refusal(f"canonical cofactor is not one: {row['curve_uid']}")
        for key in ("a4", "a6"):
            integer(curve.get(key))
        source_b = integer(source.get("b_hex"))

        matches = [
            item
            for item in corpus
            if item.get("side") == "canonical"
            and integer(item.get("n")) == integer(row["n"])
            and integer(item.get("p")) == integer(row["p"])
            and item.get("index") == row["ordinal"]
            and str(item.get("seed", "")).lower() == row["seed_hex"].lower()
        ]
        if len(matches) != 1:
            raise Refusal(f"prior corpus mapping is not unique: {row['curve_uid']}")
        corpus_record = matches[0]
        if integer(corpus_record.get("b")) != source_b:
            raise Refusal(f"canonical b mismatch: {row['curve_uid']}")
        if not all(corpus_record.get(key) is True for key in PRIOR_BOOLEANS):
            raise Refusal(f"prior corpus booleans incomplete: {row['curve_uid']}")

        result[row["curve_uid"]] = {
            "label": label,
            "curve_id": row["curve_id"],
            "p": str(integer(row["p"])),
            "n": str(integer(row["n"])),
            "a4": str(integer(curve["a4"])),
            "a6": str(integer(curve["a6"])),
            "b": str(source_b),
            "cofactor": 1,
            "corpus_record_sha256": canonical_json_digest(corpus_record),
            "provenance_record_sha256": canonical_json_digest(source),
            "prior_booleans": {key: True for key in PRIOR_BOOLEANS},
        }

    expected = {row["curve_uid"] for row in rows}
    if set(result) != expected:
        raise Refusal("prior mapping is not a complete exact 21-UID mapping")
    return result


def parse_dfd(data_path: Path) -> dict[int, list[dict[str, Any]]]:
    """Parse only actual ``ecpp.DfD`` records, retaining raw-byte locations."""
    source = data_path / "ecpp.DfD"
    raw = source.read_bytes()
    records: dict[int, list[dict[str, Any]]] = {}
    grammar = re.compile(rb"^\(\((?P<factors>[0-9 ]*)\) (?P<d>-?[0-9]+) (?P<sign>-?[0-9]+)\)\r?$", re.M)
    for ordinal, match in enumerate(grammar.finditer(raw)):
        d = int(match.group("d"))
        positions = records.setdefault(d, [])
        positions.append({
            "file": "ecpp.DfD",
            "record": ordinal,
            "byte_offset": match.start("d"),
            "line": raw.count(b"\n", 0, match.start("d")) + 1,
            "factors": match.group("factors").split(),
            "class_number_sign_code": int(match.group("sign")),
        })
    if records.get(0) is None:
        raise Refusal("actual ecpp.DfD catalog lacks its required D=0 record")
    if 1 in records:
        raise Refusal("unexpected D=1 catalog entry; source binding must be re-reviewed")
    return records


def _trace_event(kind: str, offset: int, line: bytes, **extra: Any) -> dict[str, Any]:
    return {
        "kind": kind,
        "printed": True,
        "source_offset": offset,
        "raw_utf8": line.decode("utf-8", "replace"),
        "raw_hex": line.hex(),
        **extra,
    }


def extract_trace(serial: bytes, data_path: Path | None = None) -> dict[str, Any]:
    """Extract only source-recognized printed lines, retaining all percent lines.

    Offsets are byte positions in ``serial``.  They are deliberately calculated
    before CRLF presentation handling and therefore remain correct for a guest
    that emits CRLF.  Unknown percent-prefixed output becomes a retained marker,
    not omitted evidence and not a reconstructed branch.
    """
    catalog = parse_dfd(DATA if data_path is None else data_path)
    known = (
        ("phase", re.compile(rb"^% Starting phase (?:1: building the sequence of primes|2: proving)$")),
        ("proving_job", re.compile(rb"^% Starting proving job for step ([0-9]+)$")),
        ("recursive_N", re.compile(rb"^% N_([0-9]+)=([0-9]+)$")),
        ("recursive_status", re.compile(rb"^% N_([0-9]+) is (prime|not prime)$")),
        ("retry", re.compile(rb"^%!% Forced to retry, snif\.\.\.$")),
        ("catalog_D", re.compile(rb"^% next D is (-?[0-9]+)$")),
        ("stored_D", re.compile(rb"^% D\[\[([0-9]+)\]\]=(-?[0-9]+)$")),
        ("proving_route", re.compile(rb"^% (?:No N-1 test|No N\+1 test|Cofactor is 1)$")),
        ("factor_list", re.compile(rb"^% (?:Factors are|[0-9]+\^[0-9]+.*)$")),
    )
    events: list[dict[str, Any]] = []
    for match in re.finditer(rb"[^\n]*(?:\n|$)", serial):
        raw_line = match.group(0)
        if not raw_line:
            continue
        line = raw_line[:-1] if raw_line.endswith(b"\n") else raw_line
        if line.endswith(b"\r"):
            line = line[:-1]
        if not line:
            continue
        for kind, grammar in known:
            found = grammar.match(line)
            if found is None:
                continue
            values = [part.decode("ascii") for part in found.groups()]
            if kind in {"catalog_D", "stored_D"}:
                value = int(values[-1])
                special = None
                positions = catalog.get(value, [])
                if value == 1:
                    special = "D=1 has no ecpp.DfD record; source switches D<=1 to route -1 or 1"
                elif value <= 1 and value not in catalog:
                    special = "D<=1 special source route without a catalog record"
                events.append(_trace_event(
                    kind,
                    match.start(),
                    line,
                    value=value,
                    index=int(values[0]) if kind == "stored_D" else None,
                    catalog_positions=positions,
                    special_route= special,
                ))
            else:
                events.append(_trace_event(kind, match.start(), line, value=values or None))
            break
        else:
            if line.startswith(b"%"):
                events.append(_trace_event("unknown_marker", match.start(), line))
    return {
        "schema": "trace_schema.json",
        "raw_serial_sha256": sha_bytes(serial),
        "events": events,
        "unprinted_state": "UNOBSERVED",
        "inference_prohibited": "unprinted branches are not reconstructed as attempted",
    }


def verify_supervisor(output: Path, binding: Path, index: int, digests: dict[str, str]) -> dict[str, Any]:
    if not output.is_dir() or output.is_symlink():
        raise Refusal("output must be a supervisor-created ordinary directory")
    if not binding.is_file() or binding.is_symlink():
        raise Refusal("exact external input-binding manifest is required")
    names = {entry.name for entry in output.iterdir()}
    if names != SUPERVISOR_FILES:
        raise Refusal("fresh supervisor directory must initially contain exactly its five provenance files")
    manifest = read_json(binding)
    if manifest.get("schema") != "crypto.autoresearch.nistseed_ecpp_trial_binding.v1":
        raise Refusal("binding manifest schema mismatch")
    if manifest.get("cohort_index") != index:
        raise Refusal("binding manifest cohort index mismatch")
    if Path(manifest.get("output_directory", "")).resolve() != output.resolve():
        raise Refusal("binding manifest output directory mismatch")
    if manifest.get("frozen_input_sha256") != digests:
        raise Refusal("binding manifest frozen digest mismatch")
    if manifest.get("limits") != LIMITS or manifest.get("primary_configuration") != PRIMARY:
        raise Refusal("binding manifest runtime configuration mismatch")

    launch = read_json(output / "launch.json")
    environment = read_json(output / "environment.json")
    argv = json.loads((output / "command.txt").read_text(encoding="utf-8"))
    if not isinstance(argv, list) or not all(isinstance(item, str) for item in argv):
        raise Refusal("supervisor command.txt is not a JSON argv list")
    if launch.get("argv") != argv:
        raise Refusal("launch.json argv and command.txt disagree")
    if str(index) not in argv or str(output) not in argv or str(binding) not in argv:
        raise Refusal("supervisor argv lacks index/output/binding identity")
    if not isinstance(launch.get("authority"), dict) or not isinstance(environment, dict):
        raise Refusal("supervisor launch or environment provenance is incomplete")
    return manifest


def safe_inventory(root: Path) -> dict[str, str]:
    """Return the exact regular-file inventory below an owned child directory."""
    if not root.is_dir() or root.is_symlink():
        raise Refusal("owned child directory absent or symlinked")
    resolved_root = root.resolve()
    inventory: dict[str, str] = {}
    for path in sorted(root.rglob("*")):
        if path.is_symlink():
            raise Refusal(f"symlink in owned raw artifact tree: {path}")
        if path.is_dir():
            continue
        if not path.is_file() or not path.resolve().is_relative_to(resolved_root):
            raise Refusal(f"unsafe raw artifact path: {path}")
        inventory[path.relative_to(root).as_posix()] = sha_file(path)
    if not inventory:
        raise Refusal("owned child raw artifact inventory is empty")
    return inventory


def _manifest_text() -> str:
    return (
        "run:\n"
        "  attack_claimed: false\n"
        "  result:\n"
        "    raw_result: raw-result.json\n"
        "  status_note: legacy behavior observation only; no primality, historical, curve-security, or ECDLP conclusion\n"
    )


def emit(output: Path, raw: dict[str, Any], observation: dict[str, Any], failure: dict[str, Any] | None) -> dict[str, Any]:
    write_json(output / "observation.json", observation)
    if failure is not None:
        write_json(output / "failure.json", failure)
    raw["driver_artifacts"] = safe_inventory(output / "legacy-child") if (output / "legacy-child").exists() else {}
    write_json(output / "raw-result.json", raw)
    (output / "manifest.yaml").write_text(_manifest_text(), encoding="utf-8")
    return raw


def _default_legacy_call(index: int, destination: Path, cache: Path) -> dict[str, Any]:
    """Future-only production bridge; intentionally unused by the test suite."""
    sys.path.insert(0, str(COMPAT))
    import cohort_case  # Imported only after every static binding has passed.
    import qemu_controls

    source_runtime = qemu_controls.RUNTIME
    cache.mkdir(mode=0o700)
    kernel = source_runtime / "vmlinuz-lts"
    if not kernel.is_file() or kernel.is_symlink():
        raise Refusal("frozen runtime kernel unavailable for private cache")
    os.link(kernel, cache / "vmlinuz-lts")
    (cache / "images").mkdir(mode=0o700)
    qemu_controls.RUNTIME = cache
    try:
        return cohort_case.execute_case(index, destination)
    finally:
        qemu_controls.RUNTIME = source_runtime


def run_trial(
    index: int,
    output: Path,
    binding: Path,
    legacy_call: Callable[[int, Path, Path], dict[str, Any]] | None = None,
) -> dict[str, Any]:
    if type(index) is not int or not 0 <= index < 21:
        raise Refusal("cohort index outside [0,20]")
    frozen = verify_frozen()
    rows, runtime = load_cohort()
    external_manifest = verify_supervisor(output, binding, index, frozen)
    mapping = prior_mapping(rows)
    row = rows[index]

    copied_manifest = output / "input-binding-manifest.json"
    shutil.copyfile(binding, copied_manifest)
    if copied_manifest.read_bytes() != binding.read_bytes():
        raise Refusal("copied input-binding manifest byte mismatch")
    child = output / "legacy-child"
    cache = output / "runtime-cache"
    if child.exists() or cache.exists():
        raise Refusal("reused child destination or private cache")

    raw = {
        "schema": "crypto.autoresearch.nistseed_ecpp_raw_result.v4",
        "cohort_index": index,
        "curve": row,
        "input_binding_manifest_sha256": sha_file(copied_manifest),
        "external_binding_manifest_sha256": sha_file(binding),
        "frozen_input_sha256": frozen,
        "runtime_payloads": runtime["artifacts"],
        "kernel": runtime["kernel"],
        "original_data": runtime["original_data"],
        "limits": LIMITS,
        "primary_configuration": PRIMARY,
        "supervisor_artifact_sha256": {
            name: sha_file(output / name)
            for name in SUPERVISOR_FILES
        },
        "supervisor_manifest": external_manifest,
        "prior_primality_mapping": mapping,
        "named_orders_executed": 1,
    }
    observation: dict[str, Any] = {
        "curve_uid": row["curve_uid"],
        "prior_primality_evidence": mapping[row["curve_uid"]],
        "mathematical_classification": "INDETERMINATE",
        "legacy_labels_observation_only": [],
        "stage": "bound_before_legacy_start",
        "unprinted_state": "UNOBSERVED",
        "legacy_execution_started": False,
    }

    try:
        call = legacy_call or _default_legacy_call
        result = call(index, child, cache)
        if not isinstance(result, dict):
            raise Refusal("legacy boundary did not return an observation object")
        observation.update(result)
        observation["legacy_execution_started"] = True
        serial_path = child / "prover" / "serial.raw"
        if serial_path.is_file() and not serial_path.is_symlink():
            serial = serial_path.read_bytes()
            labels = re.findall(rb"^(?:% )?This number is (prime|composite)\b", serial, re.M)
            observation["legacy_labels_observation_only"] = [label.decode("ascii") for label in labels]
            observation["trace"] = extract_trace(serial)
            observation["stage"] = "prover_observed"
        admitted = observation.get("certificate_admitted") is True
        observation["mathematical_classification"] = (
            "PRIOR_PRIMALITY_EVIDENCE_REQUIRED" if admitted else "INDETERMINATE"
        )
        raw["classification"] = observation["mathematical_classification"]
        raw["censoring"] = not admitted
        return emit(output, raw, observation, None)
    except BaseException as error:
        raw["classification"] = "INDETERMINATE"
        raw["censoring"] = True
        raw["exception"] = {"type": type(error).__name__, "message": str(error)}
        serial_path = child / "prover" / "serial.raw"
        if serial_path.is_file() and not serial_path.is_symlink():
            serial = serial_path.read_bytes()
            observation["legacy_execution_started"] = True
            observation["legacy_labels_observation_only"] = [
                label.decode("ascii")
                for label in re.findall(rb"^(?:% )?This number is (prime|composite)\b", serial, re.M)
            ]
            observation["trace"] = extract_trace(serial)
            observation["stage"] = "partial_prover_observed"
        observation["censor_reason"] = f"{type(error).__name__}: {error}"
        return emit(output, raw, observation, raw["exception"])


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--index", type=int, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--input-binding-manifest", type=Path, required=True)
    args = parser.parse_args()
    print(json.dumps(run_trial(args.index, args.output, args.input_binding_manifest), sort_keys=True))


if __name__ == "__main__":
    main()

