def dfd() -> dict[int, list[dict[str, Any]]]:
    raw = (DATA / "ecpp.DfD").read_bytes()
    grammar = re.compile(rb"^\(\((?P<factors>[0-9 ]*)\) (?P<d>-?[0-9]+) (?P<sign>-?[0-9]+)\)\r?$", re.M)
    result: dict[int, list[dict[str, Any]]] = {}
    for ordinal, match in enumerate(grammar.finditer(raw)):
        value = int(match.group("d"))
        result.setdefault(value, []).append({
            "file": "ecpp.DfD",
            "record": ordinal,
            "byte_offset": match.start("d"),
            "line": raw.count(b"\n", 0, match.start("d")) + 1,
            "factors": match.group("factors").split(),
            "class_number_sign_code": int(match.group("sign")),
        })
    if 0 not in result or 1 in result:
        fail("source-backed DfD special-route assumptions changed")
    return result


def strict_trace(serial: bytes) -> dict[str, Any]:
    catalog = dfd()
    patterns = (
        ("phase", re.compile(rb"^% Starting phase (?:1: building the sequence of primes|2: proving)$")),
        ("proving_job", re.compile(rb"^% Starting proving job for step ([0-9]+)$")),
        ("recursive_N", re.compile(rb"^% N_([0-9]+)=([0-9]+)$")),
        ("recursive_status", re.compile(rb"^% N_([0-9]+) is (prime|not prime)$")),
        ("retry", re.compile(rb"^%!% Forced to retry, snif\.\.\.$")),
        ("catalog_D", re.compile(rb"^% next D is (-?[0-9]+)$")),
        ("stored_D", re.compile(rb"^% D\[\[([0-9]+)\]\]=(-?[0-9]+)$")),
        ("proving_route", re.compile(rb"^% (?:No N-1 test|No N\+1 test|Cofactor is 1)$")),
    )
    events: list[dict[str, Any]] = []
    for item in re.finditer(rb"[^\n]*(?:\n|$)", serial):
        source_line = item.group(0)
        if not source_line:
            continue
        line = source_line[:-1] if source_line.endswith(b"\n") else source_line
        if line.endswith(b"\r"):
            line = line[:-1]
        for kind, expression in patterns:
            match = expression.match(line)
            if match is None:
                continue
            event: dict[str, Any] = {"kind": kind, "printed": True, "source_offset": item.start(), "raw_utf8": line.decode("utf-8", "replace"), "raw_hex": line.hex()}
            values = [group.decode("ascii") for group in match.groups()]
            if kind in {"catalog_D", "stored_D"}:
                value = int(values[-1])
                event["value"] = value
                event["index"] = int(values[0]) if kind == "stored_D" else None
                event["catalog_positions"] = catalog.get(value, [])
                event["special_route"] = "D=1 has no ecpp.DfD record; source switches D<=1 to route -1 or 1" if value == 1 else None
            else:
                event["value"] = values or None
            events.append(event)
            break
        else:
            if line.startswith(b"%"):
                events.append({"kind": "unknown_marker", "printed": True, "source_offset": item.start(), "raw_utf8": line.decode("utf-8", "replace"), "raw_hex": line.hex()})
    return {"schema": "trace_schema.json", "raw_serial_sha256": digest(serial), "events": events, "unprinted_state": "UNOBSERVED", "inference_prohibited": "unprinted branches are not reconstructed as attempted"}


def require_inventory(raw: dict[str, Any], output: Path) -> dict[str, Path]:
    root = output / "legacy-child"
    declared = raw.get("driver_artifacts")
    if not isinstance(declared, dict):
        fail("missing driver-owned raw artifact inventory")
    if not root.is_dir() or root.is_symlink():
        if declared:
            fail("driver inventory claims a missing child tree")
        return {}
    actual: dict[str, Path] = {}
    for path in sorted(root.rglob("*")):
        if path.is_symlink():
            fail("symlink in driver-owned raw artifact tree")
        if path.is_dir():
            continue
        if not path.is_file() or not path.resolve().is_relative_to(root.resolve()):
            fail("unsafe driver-owned raw artifact")
        relative = path.relative_to(root).as_posix()
        actual[relative] = path
    if set(actual) != set(declared):
        fail("driver-owned raw artifact inventory is not exact")
    for relative, path in actual.items():
        if sha(path) != declared[relative]:
            fail(f"mutated raw artifact: {relative}")
    return actual


def check(output: Path) -> dict[str, Any]:
    raw = load(output / "raw-result.json")
    observation = load(output / "observation.json")
    if raw.get("schema") != "crypto.autoresearch.nistseed_ecpp_raw_result.v4":
        fail("raw result schema mismatch")
    frozen_digests = frozen()
    rows, runtime = rows_and_runtime()
    index = raw.get("cohort_index")
    if type(index) is not int or not 0 <= index < 21:
        fail("raw cohort index mismatch")
    row = rows[index]
    if raw.get("curve") != row or observation.get("curve_uid") != row["curve_uid"]:
        fail("raw/observation cohort row mismatch")
    if raw.get("frozen_input_sha256") != frozen_digests:
        fail("producer frozen digest record mismatch")
    if raw.get("runtime_payloads") != runtime.get("artifacts") or raw.get("kernel") != runtime.get("kernel") or raw.get("original_data") != runtime.get("original_data"):
        fail("runtime, kernel, payload, or original catalog binding mismatch")
    if raw.get("limits") != LIMITS or raw.get("primary_configuration") != PRIMARY:
        fail("fixed runtime limits or primary configuration mismatch")
    if raw.get("named_orders_executed") != 1:
        fail("future driver did not record exactly one index invocation")

    copied = output / "input-binding-manifest.json"
    if not copied.is_file() or copied.is_symlink() or raw.get("input_binding_manifest_sha256") != sha(copied):
        fail("copied input-binding manifest missing or mutated")
    binding = load(copied)
    if binding.get("schema") != "crypto.autoresearch.nistseed_ecpp_trial_binding.v1" or binding.get("cohort_index") != index:
        fail("copied binding manifest identity mismatch")
    if Path(binding.get("output_directory", "")).resolve() != output.resolve():
        fail("copied binding output directory mismatch")
    if binding.get("frozen_input_sha256") != frozen_digests or binding.get("limits") != LIMITS or binding.get("primary_configuration") != PRIMARY:
        fail("copied binding contents mismatch")

    for name in SUPERVISOR_FILES:
        path = output / name
        if not path.is_file() or path.is_symlink() or raw.get("supervisor_artifact_sha256", {}).get(name) != sha(path):
            fail(f"supervisor provenance mismatch: {name}")
    launch = load(output / "launch.json")
    argv = json.loads((output / "command.txt").read_text(encoding="utf-8"))
    if launch.get("argv") != argv or str(index) not in argv or str(output) not in argv:
        fail("supervisor argv mismatch")
    if raw.get("supervisor_manifest") != binding:
        fail("raw supervisor binding record mismatch")

    expected_prior = independent_prior_map(rows)
    if raw.get("prior_primality_mapping") != expected_prior:
        fail("complete independently-derived 21-row prior mapping mismatch")
    if observation.get("prior_primality_evidence") != expected_prior[row["curve_uid"]]:
        fail("row prior evidence mismatch")

    artifacts = require_inventory(raw, output)
    classification = raw.get("classification")
    if classification not in {"INDETERMINATE", "PRIOR_PRIMALITY_EVIDENCE_REQUIRED"}:
        fail("raw classification is invalid")
    if raw.get("censoring") != (classification == "INDETERMINATE"):
        fail("classification/censoring mismatch")
    if observation.get("mathematical_classification") != classification:
        fail("observation/raw classification mismatch")

    stage = observation.get("stage")
    if stage == "bound_before_legacy_start":
        if artifacts or observation.get("legacy_execution_started") is not False or not (output / "failure.json").is_file():
            fail("early censored exception has inconsistent custody or execution claim")
        return {"accepted": True, "classification": "INDETERMINATE", "censored_stage": stage}

    required_prover = {"prover/started.json", "prover/result.json", "prover/serial.raw", "prover/qemu.stderr", "prover/program.stdout"}
    if not required_prover <= set(artifacts):
        fail("prover stage claims completion without complete required raw artifacts")
    prover = load(artifacts["prover/result.json"])
    started = load(artifacts["prover/started.json"])
    serial = artifacts["prover/serial.raw"].read_bytes()
    if started.get("input_sha256") != digest((row["n"] + "\n").encode("ascii")) or started.get("data_mode") != "full":
        fail("prover input or full-catalog binding mismatch")
    if started.get("guest_limit_seconds") != LIMITS["prover_guest_seconds"] or started.get("host_limit_seconds") != LIMITS["prover_host_seconds"]:
        fail("prover limit mismatch")
    if prover.get("serial_sha256") != digest(serial):
        fail("prover result serial digest mismatch")
    strict = valid_frame(prover.get("qemu_exit"), serial, prover.get("reason"))
    labels = [item.decode("ascii") for item in re.findall(rb"^(?:% )?This number is (prime|composite)\b", serial, re.M)]
    if observation.get("trace") != strict_trace(serial) or observation.get("legacy_labels_observation_only") != labels:
        fail("trace or observation labels are not independently serial-derived")

    if stage == "partial_prover_observed" or not strict or prover.get("child_exit") != 0:
        if classification != "INDETERMINATE" or not (output / "failure.json").is_file():
            fail("censored prover stage is inconsistent")
        return {"accepted": True, "classification": "INDETERMINATE", "censored_stage": stage}

    if observation.get("certificate_admitted") is not True:
        if classification != "INDETERMINATE":
            fail("non-admitted complete prover must be censored")
        return {"accepted": True, "classification": "INDETERMINATE", "censored_stage": "admission"}

    required_checker = {"prover/certificate.cformat", "checker/started.json", "checker/result.json", "checker/serial.raw", "checker/qemu.stderr", "checker/program.stdout"}
    if not required_checker <= set(artifacts):
        fail("admitted stage lacks complete checker/certificate raw artifacts")
    certificate = artifacts["prover/certificate.cformat"].read_bytes()
    checker = load(artifacts["checker/result.json"])
    checker_started = load(artifacts["checker/started.json"])
    checker_serial = artifacts["checker/serial.raw"].read_bytes()
    checker_stdout = artifacts["checker/program.stdout"].read_bytes()
    if checker_started.get("input_sha256") != digest(certificate):
        fail("checker input digest does not bind retained certificate")
    if checker_started.get("guest_limit_seconds") != LIMITS["checker_guest_seconds"] or checker_started.get("host_limit_seconds") != LIMITS["checker_host_seconds"]:
        fail("checker limits mismatch")
    if checker.get("serial_sha256") != digest(checker_serial):
        fail("checker serial digest mismatch")
    if not valid_frame(checker.get("qemu_exit"), checker_serial, checker.get("reason")):
        fail("checker framing failure")
    if labels != ["prime"]:
        fail("certificate admission conflicts with observed legacy labels")
    try:
        steps = parse(certificate, integer(row["n"]))
    except (ValueError, UnicodeError) as error:
        fail(f"certificate root/grammar failure: {error}")
    if not admit({**checker, "vm_valid": True}, checker_stdout, certificate, integer(row["n"])):
        fail("legacy checker rejection")
    if observation.get("certificate_steps") != steps or observation.get("certificate_sha256") != digest(certificate):
        fail("certificate step count, root, or digest mismatch")
    if classification != "PRIOR_PRIMALITY_EVIDENCE_REQUIRED":
        fail("admitted certificate classification mismatch")
    return {"accepted": True, "classification": classification, "legacy_certificate_component": "bounded legacy grammar/root/step component; not an independent general primality verifier"}


def aa_compare(left: dict[str, Any], right: dict[str, Any]) -> dict[str, Any]:
    required = {"fixture", "trace", "prover", "checker", "certificate", "classification", "labels", "runtime"}
    for value in (left, right):
        if not isinstance(value, dict) or set(value) != required:
            fail("A/A fixture schema is incomplete or has unexpected fields")
        fixture = value["fixture"]
        if not isinstance(fixture, dict) or set(fixture) != {"id", "public_input"}:
            fail("A/A fixture identity schema mismatch")
        if not isinstance(fixture["id"], str) or "curve_uid" in fixture or "n" in fixture or "p" in fixture:
            fail("A/A fixture must be a non-cohort public fixture")
    incidental = {"elapsed_host_seconds", "started_at", "finished_at", "output_directory", "temporary_path"}
    def normalize(value: Any) -> Any:
        if isinstance(value, dict):
            return {key: normalize(item) for key, item in value.items() if key not in incidental}
        if isinstance(value, list):
            return [normalize(item) for item in value]
        return value
    if normalize(left) != normalize(right):
        fail("A/A semantic mismatch")
    return {"mode": "A/A", "equal": True, "scope": "non-cohort engineering reproducibility control only; not an independent curve or cohort order"}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path)
    parser.add_argument("--aa-left", type=Path)
    parser.add_argument("--aa-right", type=Path)
    args = parser.parse_args()
    if args.aa_left or args.aa_right:
        if not args.aa_left or not args.aa_right:
            raise SystemExit("A/A requires both --aa-left and --aa-right")
        result = aa_compare(load(args.aa_left), load(args.aa_right))
    else:
        if args.output is None:
            raise SystemExit("--output is required outside A/A mode")
        result = check(args.output)
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
